personalMissionQuest.scripts:
QUEST_EVENT_TYPE = globals().get('QUEST_EVENT_TYPE') """:type: quest_definitions.QUEST_EVENT_TYPE"""
quest_progress = globals().get('quest_progress') """:type: quest_progress"""
filter = globals().get('BattleResults') """:type: battle_result_filters""" MAIN_PROGRESS_ID = 'crits' MAIN_PROGRESS_TOP_BY_EXP_ID = 'topByExp' MAIN_PROGRESS_SERIES = 'battlesSeries'
def onInit(eventType, eventData, quest, processor): for event in events.iterkeys(): processor.subscribe(event, quest) return True
def onFinishBattle(eventType, eventData, quest, processor): questProgress = quest_progress.BaseQuestProgress(quest.config, processor.getQuestProgress(quest.progressID)) brfilter = filter.BattleResultsFilter(eventData)
result = eventData['avatarResults'] topByExp = result['misc']['total']['xp'] topByExpRes = topByExp <= questProgress.getProgress(MAIN_PROGRESS_TOP_BY_EXP_ID).getParam("desiredPosition") destroyedTracks = brfilter.sumCrits(criticalType=questProgress.getProgress(MAIN_PROGRESS_ID).getParam("critTypes"))
if topByExpRes: questProgress.increaseSeriesUntilComplete(MAIN_PROGRESS_SERIES, MAIN_PROGRESS_ID, destroyedTracks)
eventData['results'].update(processor.checkComplete(questProgress, quest.progressID)) processor.setQuestProgress(quest.progressID, questProgress.save())
events = { QUEST_EVENT_TYPE.INIT: onInit, QUEST_EVENT_TYPE.FINISH_BATTLE: onFinishBattle, }
def quest(eventType, eventData, quest, processor): LOG('QUEST EVENT:', eventType, quest.id) return events.get(eventType, lambda *args: False)(eventType, eventData, quest, processor)
